draw:
function arrow(x1,y1,x2,y2,col,wid){
  ctx.strokeStyle=col; ctx.fillStyle=col; ctx.lineWidth=wid;
  ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  var a=Math.atan2(y2-y1,x2-x1), s=7;
  ctx.beginPath();
  ctx.moveTo(x2,y2);
  ctx.lineTo(x2-s*Math.cos(a-0.4), y2-s*Math.sin(a-0.4));
  ctx.lineTo(x2-s*Math.cos(a+0.4), y2-s*Math.sin(a+0.4));
  ctx.closePath(); ctx.fill();
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var I = p.current, d = p.dist / 100, Lh = p.half / 100;
var sinMax = Lh / Math.sqrt(Lh * Lh + d * d);
var B = 2e-7 * I / d * sinMax;
var Binf = 2e-7 * I / d;

var pad = 30;
var span = Math.max(Lh, d) * 1.25;
var sc = Math.min((W - 2 * pad) / (2 * span), (H - 2 * pad) / (1.5 * span));
var ox = W / 2, oy = H * 0.78;
var X = function (x) { return ox + x * sc; };
var Y = function (y) { return oy - y * sc; };

// full line the wire lies on
ctx.strokeStyle = C.faint; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();

// the segment itself
ctx.strokeStyle = C.accent; ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(X(-Lh), Y(0)); ctx.lineTo(X(Lh), Y(0)); ctx.stroke();
arrow(X(0), Y(0), X(0) + 22, Y(0), C.accent, 2);
ctx.fillStyle = C.accent;
ctx.fillText("I = " + I.toFixed(1) + " A", X(0) + 26, Y(0) + 16);

// field point
var Px = X(0), Py = Y(d);
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(Px, Py); ctx.lineTo(X(0), Y(0)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(Px, Py, 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("P", Px + 8, Py - 6);
ctx.fillText("d = " + (d * 100).toFixed(0) + " cm", Px + 8, (Py + Y(0)) / 2);

// the two end angles
ctx.strokeStyle = C.figure; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(Px, Py); ctx.lineTo(X(Lh), Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(Px, Py); ctx.lineTo(X(-Lh), Y(0)); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("angle to each end", Px + 14, Py + 20);

// travelling element and its contribution
var per = 4.0;
var u = (t % per) / per;
var xs = -Lh + 2 * Lh * u;
var r2 = xs * xs + d * d;
var dB = d / Math.pow(r2, 1.5);
var dBmax = 1 / (d * d);
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(xs), Y(0), 4, 0, Math.PI * 2); ctx.fill();
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(X(xs), Y(0)); ctx.lineTo(Px, Py); ctx.stroke();
var bar = 4 + 26 * (dB / dBmax);
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(Px, Py, bar, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("size of this element's share", Px + bar + 8, Py + 4);

out.note = "B at P = " + (B * 1e6).toFixed(2) + " microtesla, which is " + (100 * B / Binf).toFixed(1) + " percent of what an endless wire would give (" + (Binf * 1e6).toFixed(2) + " microtesla)";
